using Contoso.Orders;

namespace Contoso.Orders.Tests;

[TestClass]
public sealed class OrderServiceTests
{
    private readonly OrderService _sut;

    public OrderServiceTests()
    {
        _sut = new OrderService();
    }

    private static List<OrderItem> CreateItems(params (string name, decimal price, int qty)[] items) =>
        items.Select(i => new OrderItem { ProductName = i.name, Price = i.price, Quantity = i.qty }).ToList();

    // --- CreateOrder: happy path ---

    [TestMethod]
    public void CreateOrder_WithSingleItem_ReturnsOrderWithCorrectTotal()
    {
        // Arrange
        var items = CreateItems(("Widget", 9.99m, 2));

        // Act
        var order = _sut.CreateOrder("cust-1", items);

        // Assert
        Assert.IsNotNull(order);
        Assert.AreEqual("cust-1", order.CustomerId);
        Assert.AreEqual(19.98m, order.Total);
        Assert.HasCount(1, order.Items);
    }

    [TestMethod]
    public void CreateOrder_WithMultipleItems_SumsTotalCorrectly()
    {
        // Arrange
        var items = CreateItems(("A", 10m, 1), ("B", 5m, 3));

        // Act
        var order = _sut.CreateOrder("cust-2", items);

        // Assert
        Assert.AreEqual(25m, order.Total); // 10*1 + 5*3
        Assert.HasCount(2, order.Items);
    }

    [TestMethod]
    public void CreateOrder_SetsNonEmptyIdAndCreatedAt()
    {
        var before = DateTime.UtcNow;
        var order = _sut.CreateOrder("cust-1", CreateItems(("X", 1m, 1)));
        var after = DateTime.UtcNow;

        Assert.IsNotNull(order.Id);
        Assert.IsTrue(order.CreatedAt >= before && order.CreatedAt <= after);
    }

    // --- CreateOrder: error cases ---

    [TestMethod]
    public void CreateOrder_NullCustomerId_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => _sut.CreateOrder(null!, CreateItems(("X", 1m, 1))));
        Assert.AreEqual("customerId", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_NullItems_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => _sut.CreateOrder("cust-1", null!));
        Assert.AreEqual("items", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_EmptyItems_ThrowsInvalidOperationException()
    {
        var ex = Assert.ThrowsExactly<InvalidOperationException>(
            () => _sut.CreateOrder("cust-1", []));
        Assert.Contains("no items", ex.Message, StringComparison.OrdinalIgnoreCase);
    }

    // --- GetOrder ---

    [TestMethod]
    public void GetOrder_ExistingId_ReturnsSameOrder()
    {
        var created = _sut.CreateOrder("cust-1", CreateItems(("X", 5m, 1)));

        var retrieved = _sut.GetOrder(created.Id);

        Assert.AreSame(created, retrieved);
    }

    [TestMethod]
    public void GetOrder_NonExistentId_ReturnsNull()
    {
        Assert.IsNull(_sut.GetOrder("does-not-exist"));
    }

    // --- GetOrdersByCustomer ---

    [TestMethod]
    public void GetOrdersByCustomer_MultipleOrders_ReturnsAll()
    {
        _sut.CreateOrder("cust-A", CreateItems(("X", 1m, 1)));
        _sut.CreateOrder("cust-A", CreateItems(("Y", 2m, 1)));
        _sut.CreateOrder("cust-B", CreateItems(("Z", 3m, 1)));

        var results = _sut.GetOrdersByCustomer("cust-A");

        Assert.HasCount(2, results);
    }

    [TestMethod]
    public void GetOrdersByCustomer_NoOrders_ReturnsEmptyList()
    {
        Assert.IsEmpty(_sut.GetOrdersByCustomer("nobody"));
    }
}

using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _sut;

    public PriceCalculatorTests()
    {
        _sut = new PriceCalculator();
    }

    // --- CalculateTotal: happy path ---

    [TestMethod]
    [DataRow(10.00, 2, 0.0, 20.00, DisplayName = "No tax")]
    [DataRow(10.00, 2, 0.1, 22.00, DisplayName = "10% tax")]
    [DataRow(0.00, 5, 0.2, 0.00, DisplayName = "Zero price")]
    [DataRow(25.00, 0, 0.1, 0.00, DisplayName = "Zero quantity")]
    public void CalculateTotal_ValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _sut.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    // --- CalculateTotal: error cases ---

    [TestMethod]
    public void CalculateTotal_NegativeQuantity_ThrowsArgumentOutOfRange()
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _sut.CalculateTotal(10m, -1, 0.1m));
        Assert.AreEqual("quantity", ex.ParamName);
    }

    [TestMethod]
    public void CalculateTotal_NegativeUnitPrice_ThrowsArgumentOutOfRange()
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _sut.CalculateTotal(-5m, 1, 0.1m));
        Assert.AreEqual("unitPrice", ex.ParamName);
    }

    [TestMethod]
    [DataRow(-0.01, DisplayName = "Negative tax")]
    [DataRow(1.01, DisplayName = "Tax over 100%")]
    public void CalculateTotal_InvalidTaxRate_ThrowsArgumentOutOfRange(double taxRate)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _sut.CalculateTotal(10m, 1, (decimal)taxRate));
        Assert.AreEqual("taxRate", ex.ParamName);
    }

    // --- ApplyDiscount ---

    [TestMethod]
    [DataRow(100.00, 10.0, 90.00, DisplayName = "10% off")]
    [DataRow(100.00, 0.0, 100.00, DisplayName = "No discount")]
    [DataRow(100.00, 100.0, 0.00, DisplayName = "Full discount")]
    public void ApplyDiscount_ValidInputs_ReturnsExpected(
        double price, double discount, double expected)
    {
        var result = _sut.ApplyDiscount((decimal)price, (decimal)discount);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(-1.0, DisplayName = "Negative discount")]
    [DataRow(101.0, DisplayName = "Discount over 100%")]
    public void ApplyDiscount_InvalidPercent_ThrowsArgumentOutOfRange(double discount)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _sut.ApplyDiscount(100m, (decimal)discount));
    }

    // --- FormatPrice ---

    [TestMethod]
    public void FormatPrice_DefaultCurrency_ReturnsDollarFormat()
    {
        Assert.AreEqual("$19.99", _sut.FormatPrice(19.99m));
    }

    [TestMethod]
    public void FormatPrice_CustomCurrency_UsesSymbol()
    {
        Assert.AreEqual("€5.00", _sut.FormatPrice(5m, "€"));
    }

    [TestMethod]
    public void FormatPrice_RoundsToTwoDecimals()
    {
        Assert.AreEqual("$1.24", _sut.FormatPrice(1.235m));
    }
}

